#include "opensim/scene/part_script_events.hpp"
#include <iostream>
using namespace opensim;using namespace scene;
namespace {
framework::Uuid id(int n){auto s=std::to_string(n);return framework::Uuid("11223344-5566-7788-99aa-"+std::string(12-s.size(),'0')+s);}
std::string probe(int mode,std::uint64_t first,std::uint64_t second,int action,int failure){auto bit=[&](int n){return (mode&n)!=0;};std::string trace;auto step=[&](int n,std::string value){trace+='|'+value;if(n==failure)throw std::runtime_error("injected");};bool group=!bit(1),root=!bit(2);PartScriptEventsBackend b;b.has_group=[&]{return group;};b.has_root=[&]{return root;};b.has_scene=[&]{return !bit(4);};b.is_root=[&]{return root&&!bit(8);};b.allowed_drop=[&]{return bit(16);};b.remove_targets=[&](auto key){step(2,"TARGETS:"+key.str());if(bit(64))group=false;};b.email=[&]()->std::optional<PartEmailEvents>{step(1,"MAIL");if(bit(32))return {};return PartEmailEvents{[&](auto){step(4,"ADDMAIL");if(bit(256))root=false;if(bit(512))group=false;},[&](auto){step(3,"REMOVEMAIL");if(bit(128))group=false;}};};b.aggregate_group=[&]{step(5,"GROUP");};b.physics_events=[&]{step(6,"PHYSICS");};b.full_update=[&]{step(7,"FULL");};PartScriptEvents events(id(9),std::move(b));events.initial_state(0xfedcba9876543210ull,0x12345678);std::string result="OK";try{if(action==0){events.set(id(1),first);events.set(id(1),first);events.set(id(2),second);events.remove(id(3));events.remove(id(1));events.aggregate();events.remove(id(2));}else if(action==1){events.set(id(1),first);events.remove(id(1));}else if(action==2)events.remove(id(1));else events.aggregate();}catch(...){result="THROW";}auto mask=[&](int n){auto value=events.events(id(n));return value?std::to_string(*value):"-";};return result+":"+std::to_string(events.aggregated())+":"+std::to_string(events.local_flags())+":"+mask(1)+":"+mask(2)+trace;}
}
int main(int argc,char** argv){try{if(argc>1&&std::string_view(argv[1])=="--probe"){int m,a,f;std::uint64_t one,two;while(std::cin>>m>>one>>two>>a>>f)std::cout<<probe(m,one,two,a,f)<<'\n';return 0;}int n=0;auto check=[&](bool value,const char* s){++n;if(!value)throw std::runtime_error(s);};check(probe(0,script_event::touch_start,0,1,0)=="OK:0:0:-:-|GROUP|GROUP","event removal reaggregates without engine dependency");check(probe(0,0,0,2,0).find('|')==std::string::npos,"missing event removal has no effects");check(probe(0,script_event::any_target,0,1,0).find("|TARGETS:")!=std::string::npos,"target registration cleanup");check(probe(0,script_event::email,0,1,0).find("|REMOVEMAIL")!=std::string::npos,"mailbox cleanup");check(probe(8,script_event::touch,0,1,0).find("|PHYSICS|FULL")!=std::string::npos,"child physics then full update");check(probe(1,0,0,3,0).starts_with("OK:18364758544493064720:305419896"),"missing parent retains stale aggregate");std::cout<<"PASS: "<<n<<" part script event checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
